package com.primehr.performancemanagement.api;import com.primehr.performancemanagement.api.PerformanceManagementTeamDtos.*;import com.primehr.performancemanagement.application.PerformanceManagementTeamService;import com.primehr.security.*;import com.primehr.shared.api.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/primehr/v1/performance-management/pmts")public class PerformanceManagementTeamController{private final PerformanceManagementTeamService service;private final PerformancePmtPermissionGuard permission;private final AgencyScopeResolver agency;public PerformanceManagementTeamController(PerformanceManagementTeamService s,PerformancePmtPermissionGuard p,AgencyScopeResolver a){service=s;permission=p;agency=a;}@GetMapping public PageResponse<TeamResponse>list(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){permission.require(PrimeHrAction.ACCESS,t);return service.list(agency.resolveAgencyId(a),page,size);}@GetMapping("/{id}")public TeamResponse get(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){permission.require(PrimeHrAction.ACCESS,t);return service.get(agency.resolveAgencyId(a),id);}@PostMapping@ResponseStatus(HttpStatus.CREATED)public TeamResponse create(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@Valid@RequestBody SaveTeam r){permission.require(PrimeHrAction.ADD,t);return service.create(agency.resolveAgencyId(a),r,t,c);}@PutMapping("/{id}")public TeamResponse update(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody SaveTeam r){permission.require(PrimeHrAction.EDIT,t);return service.update(agency.resolveAgencyId(a),id,r,t,c);}@PutMapping("/{id}/members")public TeamResponse members(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody MembersInput r){permission.require(PrimeHrAction.EDIT,t);return service.members(agency.resolveAgencyId(a),id,r,t,c);}@PostMapping("/{id}/activate")public TeamResponse activate(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody Transition r){permission.require(PrimeHrAction.PUBLISH,t);return service.activate(agency.resolveAgencyId(a),id,r,t,c);}@PostMapping("/{id}/deactivate")public TeamResponse deactivate(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody Transition r){permission.require(PrimeHrAction.PUBLISH,t);return service.deactivate(agency.resolveAgencyId(a),id,r,c);}}
